SELECT CASE WHEN customers.credit_limit >= 15300 THEN 'high' WHEN customers.credit_limit >= 3500 THEN 'mid' ELSE 'low' END credit_limit_bucket, customers.segment, MIN(accounts.balance) min_balance FROM accounts INNER JOIN customers ON customers.id = accounts.customer_id GROUP BY CASE WHEN customers.credit_limit >= 15300 THEN 'high' WHEN customers.credit_limit >= 3500 THEN 'mid' ELSE 'low' END, customers.segment ORDER BY customers.segment;
